import { Component, OnInit } from '@angular/core';
import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { ActivatedRoute, Router } from '@angular/router';
import { G } from '../../../../core/common/G';

@Component({
  selector: 'app-access-denied',
  templateUrl: './access-denied.component.html',
  styleUrls: ['./access-denied.component.scss']
})
export class AccessDeniedComponent implements OnInit {

  msg = '';
  isMsg = false;
  isFound = false;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  isInfoShow = false;
  isInfoShow2 = false;
  msgParam = '';
  link: string | SafeUrl = '';
  link2: string | SafeUrl = '';
  video: string | SafeUrl = 'brfwi7w';
  video2: string | SafeUrl = 'brfwi7w';

  constructor(
    private activatedRoute: ActivatedRoute,
    private sanitizer: DomSanitizer,
    private router: Router) { }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.link = G.TeacherRegisterLink;
    this.link2 = G.SellerRegisterLink;
    this.video = G.TeacherRegisterVideo;
    this.video2 = G.SellerRegisterVideo;

    this.activatedRoute.params.subscribe(params => {

      const msg = params.msg;
      this.msgParam = msg;
      this.isFound = false;

      if (msg === undefined) {
        this.msg = '';
        this.isMsg = false;
      } else {

        if (msg === 'deactive') {
          this.msg = `اکانت شما در مرحله فعال سازی است.
           برای اطلاعات بیشتر با پشتیبانی تماس حاصل فرمایید`;
        } else if (msg === 'deactive2') {
          this.msg = `اکانت شما در مرحله فعال سازی است.
          برای اطلاعات بیشتر با پشتیبانی تماس حاصل فرمایید`;
        } else if (msg === 'TunerPlus') {
          this.msg = 'TunerPlus';
          this.isFound = true;
        } else if (msg === 'TunerPlusTuning') {
          this.msg = 'TunerPlusTuning';
          this.isFound = true;
        }  else if (msg === 'TunerPlusStoichiometry') {
          this.msg = 'TunerPlusStoichiometry';
          this.isFound = true;
        } else if (msg === 'AccessDeniedTunerInj') {
          this.msg = 'AccessDeniedTunerInj';
          this.isFound = true;
        } else {
          this.msg = msg;
        }

        this.isMsg = true;
      }
    });
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  checkURL() {
    let url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.video +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    let url = 'https://www.aparat.com/v/' +
      this.video;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkURL2() {
    let url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.video2 +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl2() {
    let url = 'https://www.aparat.com/v/' +
      this.video2;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

}
